-- Inserts 77 catalog_phase_unit_notes rows from the old transmissions table's
-- per-vehicle `notes` column, mapped to catalog phase(s) by brand + generation code (or, for
-- the handful of old vehicles with no generation code in their model string at all, by brand +
-- model name alone, applied to every phase of that model sharing the car's one generation --
-- old vehicles are one row per generation). Generated by
-- scripts/fill/write-gearbox-notes-migration.mjs. Requires
-- 20261011213839_add_catalog_phase_unit_notes.sql to already be live -- the precondition
-- below checks the table exists before doing anything else.
--
-- Insert-only, each guarded individually (ON CONFLICT DO NOTHING against the table's own
-- unique(phase_id, unit_id)). Deliberately excludes: notes for a (brand, generation) whose
-- catalog phase doesn't actually use this unit (skipped, not saved anywhere -- the note
-- would be misleading there); notes for a (brand, generation) with no catalog phase seeded
-- yet at all (saved instead to scripts/fill/pending-gearbox-notes.csv for later).
--
-- Review-only: NOT run by this session. Run once, in a fresh SQL editor tab, AFTER
-- 20261011213839 has been applied.

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.catalog_phase_unit_notes') IS NULL THEN
    RAISE EXCEPTION 'catalog_phase_unit_notes does not exist -- run 20261011213839 first.';
  END IF;
END $$;

